{"packet_id":"D052-02","doc_id":"D052","jurisdiction":"MA","category":"security_deposits","lifecycle":"enacted","title":"Successor liability for security deposit on transfer of the dwelling unit","requirement":"A lessor who transfers the dwelling unit remains liable under this section until the rental advance is credited to the successor and the tenant is notified, or the advance and interest are credited to the tenant; if the lessor fails to credit the successor, the successor assumes liability for crediting the advance and paying interest.","key_value":null,"coverage_conditions":"Applies to lessors and their agents who receive a security deposit or rental advance and transfer their interest in the dwelling unit; does not apply to a city or town acquiring title under chapter sixty, a foreclosing mortgagee, or a mortgagee in possession that is a chartered financial institution.","applicability":{"built_on_or_before":null,"built_after":null,"date_basis":null,"min_units":null,"max_units":null,"owner_dependent":false,"other":"Lessors transferring interest in a dwelling unit; exemption for municipalities and chartered financial-institution mortgagees"},"exemptions":"A city or town acquiring title to property pursuant to chapter sixty, or a foreclosing mortgagee or a mortgagee in possession that is a financial institution chartered by the commonwealth or by the United States.","penalty":null,"effective_date":null,"citation":"G.L. c. 186, § 15B","quoted_span":"In the event that the lessor fails to credit said rental advance to his successor in interest as required by this subsection, the successor in interest shall, without regard to the nature of the transfer, assume liability for crediting of the rental advance, and payment of all interest thereon to the tenant in accordance with the provisions of this section","interaction":null,"confidence":0.95,"conflict_flag":false,"conflict_note":null}
{"packet_id":"D052-02","doc_id":"D052","jurisdiction":"MA","category":"security_deposits","lifecycle":"enacted","title":"Exemption for short-term vacation or recreational rentals","requirement":"The security deposit provisions of this section do not apply to any lease, rental, occupancy or tenancy of one hundred days or less that is for a vacation or recreational purpose.","key_value":"100 days or less","coverage_conditions":"Excludes from this section any lease, rental, occupancy or tenancy of one hundred days or less in duration made for a vacation or recreational purpose.","applicability":{"built_on_or_before":null,"built_after":null,"date_basis":null,"min_units":null,"max_units":null,"owner_dependent":false,"other":"Vacation or recreational rentals of 100 days or less are excluded"},"exemptions":"Leases, rentals, occupancies or tenancies of one hundred days or less for a vacation or recreational purpose.","penalty":null,"effective_date":null,"citation":"G.L. c. 186, § 15B","quoted_span":"The provisions of this section shall not apply to any lease, rental, occupancy or tenancy of one hundred days or less in duration which lease or rental is for a vacation or recreational purpose.","interaction":null,"confidence":0.95,"conflict_flag":false,"conflict_note":null}
